mapper.insert:
INSERT INTO REGION (
    region_id,
    region_name,
    parent_region_id
) VALUES (
    #{regionId},
    #{regionName},
    #{parentRegionId}
)
ON DUPLICATE KEY UPDATE
    region_name = VALUES(region_name),
    parent_region_id = VALUES(parent_region_id);

INSERT INTO PLACE_IMAGE (
    place_id,
    image_url,
    sort_order
) VALUES (
    #{placeId},
    #{imageUrl},
    #{sortOrder}
);

mapper.select:
SELECT p.place_id AS placeId, p.member_id AS memberId, p.region_id AS regionId, p.place_type AS placeType, p.name, p.description, p.address, p.mapx, p.mapy, p.is_closed AS isClosed, p.created_at AS createdAt, p.updated_at AS updatedAt, p.first_image AS firstImage, p.hashtags, p.min_price AS minPrice, p.use_fee_info AS useFeeInfo, p.people_count AS peopleCount, r.region_name AS regionName FROM PLACE p LEFT JOIN REGION r ON p.region_id = r.region_id WHERE p.place_type = #{placeType}
AND p.region_id = #{regionId}
ORDER BY p.created_at DESC
